4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest case ---
6	  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums per main item type ---
16	  it("should quote a plain sword — premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
17	    const result = runScenario({
18	      customer: { yearsWithMHPCO: 0 },
19	      steps: [
20	        {
21	          op: "quote",
22	          items: [
23	            { type: "sword", material: "steel", enchantment: 3, cursed: false },
24	          ],
25	        },
26	      ],
27	    });
28	
29	    expect(result).toEqual({ results: [{ premium: 115 }] });
30	  });
31	  it("should quote a plain amulet — premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
32	    const result = runScenario({
33	      customer: { yearsWithMHPCO: 0 },
34	      steps: [
35	        {
36	          op: "quote",
37	          items: [
38	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
39	          ],
40	        },
41	      ],
42	    });
43	
44	    expect(result).toEqual({ results: [{ premium: 71 }] });
45	  });
46	  it("should quote a plain staff — premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
47	    const result = runScenario({
48	      customer: { yearsWithMHPCO: 0 },
49	      steps: [
50	        {
51	          op: "quote",
52	          items: [
53	            { type: "staff", material: "oak", enchantment: 2, cursed: false },
54	          ],
55	        },
56	      ],
57	    });
58	
59	    expect(result).toEqual({ results: [{ premium: 93 }] });
60	  });
61	  it("should quote a plain potion — premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
62	    const result = runScenario({
63	      customer: { yearsWithMHPCO: 0 },
64	      steps: [
65	        {
66	          op: "quote",
67	          items: [
68	            { type: "potion", material: "glass", enchantment: 1, cursed: false },
69	          ],
70	        },
71	      ],
72	    });
73	
74	    expect(result).toEqual({ results: [{ premium: 49 }] });
75	  });
76	
77	  // --- Component base premiums and the block of 3 alike ---
78	  it("should quote a single rune — base premium 25 G", () => {
79	    const result = runScenario({
80	      customer: { yearsWithMHPCO: 0 },
81	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
82	    });
83	
84	    // 25 base + 10% first insurance + 5 fee = 32.5, rounded up to 33 in
85	    // MHPCO's favour.
86	    expect(result).toEqual({ results: [{ premium: 33 }] });
87	  });
88	  it("should quote a single moonstone — base premium 25 G", () => {
89	    const result = runScenario({
90	      customer: { yearsWithMHPCO: 0 },
91	      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
92	    });
93	
94	    // As with the rune test: 25 base + 10% + 5 fee = 32.5, rounded up to 33.
